package com.company.platform.commerce.infrastructure;
import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.stereotype.Component; import java.util.UUID;
@Component public class SecurityTenantContextProvider implements TenantContextProvider { public UUID currentTenantId(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new IllegalStateException("authenticated tenant context required");if(a instanceof JwtAuthenticationToken jwt){Object value=jwt.getToken().getClaims().getOrDefault("tenant_id",jwt.getToken().getClaims().get("tenantId"));if(value!=null)return UUID.fromString(value.toString());}throw new IllegalStateException("tenant_id claim required");} }
